const state = $getWorkflowStaticData('global');

const videos = playlistVideos($input.all());

// 空列表、或每条都没有 videoId：不推进度
if (videos.length === 0) return [];

const pending = pendingVideos(videos, state.youtubeLikesLastVideoId);
state.youtubeLikesLastVideoId = videos[0].json.videoId;

// 从旧到新发送，频道里最后一条是最新点赞
return pending.reverse();

function playlistVideos(items) {
  const positionOf = (item) => {
    const value = item?.json?.snippet?.position;
    const position = typeof value === 'number' ? value : Number.parseInt(value, 10);
    return Number.isFinite(position) ? position : Number.POSITIVE_INFINITY;
  };

  const seen = new Set();

  return items
    .slice()
    .sort((a, b) => positionOf(a) - positionOf(b))
    .map(toVideo)
    .filter((item) => {
      const videoId = item?.json?.videoId;
      if (!videoId || seen.has(videoId)) return false;
      seen.add(videoId);
      return true;
    });
}

function pendingVideos(videos, lastId) {
  const cursor = typeof lastId === 'string' && lastId ? lastId : undefined;

  // 第一次只记下最新一条，不推送已有视频
  if (!cursor) return [];

  const cursorIndex = videos.findIndex((item) => item.json.videoId === cursor);

  // 进度已经不在这批结果里：整批推送，不翻页
  if (cursorIndex === -1) return videos.slice();

  // 进度那条已经发过，只取排在它前面的视频
  return videos.slice(0, cursorIndex);
}

function toVideo(item) {
  const json = item?.json;
  if (!json || typeof json !== 'object') return null;

  const snippet = json.snippet ?? {};
  const videoId = json.contentDetails?.videoId || snippet.resourceId?.videoId || '';
  if (!videoId) return null;

  const thumbnails = snippet.thumbnails ?? {};
  const thumbnail = ['maxres', 'standard', 'high', 'medium', 'default']
    .map((size) => thumbnails[size]?.url)
    .find((url) => typeof url === 'string' && url) ?? '';
  const title = snippet.title ?? '';
  const message = [
    `▶️ ${escapeHtml(title)} #video #youtube`,
    `https://www.youtube.com/watch?v=${videoId}`,
  ].join('\n\n');

  return {
    json: {
      videoId,
      title,
      channelTitle: snippet.videoOwnerChannelTitle || '',
      url: `https://www.youtube.com/watch?v=${videoId}`,
      thumbnail,
      likedAt: snippet.publishedAt ?? '',
      message,
    },
    pairedItem: item.pairedItem,
  };
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
